import{describe,it,expect}from"vitest";import{monuments,monumentEras,getMonumentById,getMonumentsByEra,getMonumentsByCity,filterMonuments}from"../../frontend/up-monuments/up-monuments.js";const REQUIRED_MONUMENT_FIELDS=["id","name","city","builtYear","builtBy","era","style","materials","unesco","icon","description","architectureDetails","galleryImages"],MANDATORY_MONUMENT_IDS=["taj_mahal","agra_fort","fatehpur_sikri","bara_imambara","chota_imambara","rumi_darwaza","jhansi_fort"];describe("Famous Monuments Dataset Integrity",()=>{it("contains at least 7 iconic Uttar Pradesh monuments",()=>{expect(monuments.length).toBeGreaterThanOrEqual(7)}),it("contains all 7 mandatory specified monuments",()=>{const e=monuments.map(e=>e.id.toLowerCase());MANDATORY_MONUMENT_IDS.forEach(t=>{expect(e,`Missing mandatory monument ${t}`).toContain(t)})}),it("every monument object contains all required fields with valid types",()=>{monuments.forEach((e,t)=>{REQUIRED_MONUMENT_FIELDS.forEach(a=>{expect(e,`Monument at index ${t} missing field ${a}`).toHaveProperty(a),"unesco"===a?expect(typeof e.unesco).toBe("boolean"):"architectureDetails"===a?(expect(typeof e.architectureDetails).toBe("object"),expect(e.architectureDetails).toHaveProperty("keyStructures"),expect(Array.isArray(e.architectureDetails.keyStructures)).toBe(!0)):"galleryImages"===a?(expect(Array.isArray(e.galleryImages)).toBe(!0),expect(e.galleryImages.length).toBeGreaterThan(0)):(expect(typeof e[a]).toBe("string"),expect(e[a].trim().length).toBeGreaterThan(0))})})}),it("all monument IDs are unique",()=>{const e=monuments.map(e=>e.id);expect(new Set(e).size).toBe(e.length)})}),describe("Monument Query Helpers",()=>{it("retrieves monument profile by ID or name",()=>{const e=getMonumentById("taj_mahal");expect(e).toBeDefined(),expect(e.name).toBe("Taj Mahal"),expect(e.city).toBe("Agra");const t=getMonumentById("Bara Imambara");expect(t).toBeDefined(),expect(t.id).toBe("bara_imambara")}),it("retrieves monuments filtered by historical era",()=>{const e=getMonumentsByEra("Mughal Era");expect(e.length).toBeGreaterThanOrEqual(3);const t=e.map(e=>e.id);expect(t).toContain("taj_mahal"),expect(t).toContain("agra_fort");const a=getMonumentsByEra("Awadhi");expect(a.length).toBeGreaterThanOrEqual(3)}),it("retrieves monuments filtered by city",()=>{const e=getMonumentsByCity("Agra");expect(e.length).toBeGreaterThanOrEqual(3);const t=getMonumentsByCity("Lucknow");expect(t.length).toBeGreaterThanOrEqual(3)})}),describe("Search & Filter Helpers",()=>{it("filters monuments by search query (e.g. Shah Jahan or Bhool Bhulaiya)",()=>{const e=filterMonuments("Shah Jahan");expect(e.length).toBeGreaterThan(0),expect(e[0].id).toBe("taj_mahal");const t=filterMonuments("Bhool Bhulaiya");expect(t.length).toBeGreaterThan(0),expect(t[0].id).toBe("bara_imambara")}),it("filters monuments by era and city combined",()=>{const e=filterMonuments("","Mughal","Agra");expect(e.length).toBeGreaterThanOrEqual(3)}),it("returns empty array when search query matches nothing",()=>{const e=filterMonuments("NonExistentMonumentXYZ");expect(e).toEqual([])})});